const row = $('Wenn von anderem Workflow aufgerufen').first().json;
const r = $json;
const code = r.statusCode || null;
const fehlerText = r.error ? (typeof r.error === 'string' ? r.error : r.error.message || JSON.stringify(r.error)) : '';

// Hinweis: Im n8n-Code-Knoten gibt es kein "new URL(...)".
// Deshalb zerlegen wir Adressen mit einem regulären Ausdruck selbst.
function zerlegeUrl(roh) {
  const m = String(roh || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  return { protokoll: m[1].toLowerCase(), host: m[2].toLowerCase(), pfad: m[3] || '/', query: m[4] || '' };
}

// Macht aus einer relativen Weiterleitung ("/karriere") eine volle Adresse.
function absoluteUrl(ziel, basis) {
  if (/^https?:\/\//i.test(ziel)) return ziel;
  const b = zerlegeUrl(basis);
  if (!b) return ziel;
  if (ziel.startsWith('//')) return b.protokoll + ':' + ziel;
  if (ziel.startsWith('/')) return b.protokoll + '://' + b.host + ziel;
  return b.protokoll + '://' + b.host + b.pfad.replace(/[^\/]*$/, '') + ziel;
}

// Zeigt eine Adresse nur noch auf eine allgemeine Karriere- oder Startseite?
function istAllgemeineSeite(ziel, original) {
  const z = zerlegeUrl(ziel);
  const o = zerlegeUrl(original);
  if (!z || !o) return false;
  const pfad = (u) => u.pfad.replace(/\/+$/, '').toLowerCase();
  const host = (u) => u.host.replace(/^www\./, '');
  if (host(z) === host(o) && pfad(z) === pfad(o)) return false; // z. B. nur http -> https
  const p = pfad(z);
  if (p === '') return true;
  if (/^(\/[a-z]{2}(-[a-z]{2})?)?(\/(karriere|career|careers|jobs|job|stellenangebote|stellen|offene-stellen|jobboerse|join-us|joinus|vacancies|work-with-us|search|suche))*$/.test(p)) return true;
  if (/[?&](error|expired|notfound|jobnotfound)=/i.test(z.query)) return true;
  return false;
}

let entscheidung = 'weiter';
let hinweis = '';
if (/ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(fehlerText)) {
  entscheidung = 'tot';
  hinweis = 'Domain existiert nicht (mehr)';
} else if (code === 404 || code === 410) {
  entscheidung = 'tot';
  hinweis = `HTTP ${code}: Seite gibt es nicht mehr`;
} else if (code >= 300 && code < 400) {
  const loc = r.headers && (r.headers.location || r.headers.Location);
  if (loc) {
    const ziel = absoluteUrl(loc, row.url);
    if (istAllgemeineSeite(ziel, row.url)) {
      entscheidung = 'tot';
      hinweis = `Weiterleitung auf allgemeine Seite: ${ziel}`;
    }
  }
}

return {
  json: {
    ...row,
    status: entscheidung === 'tot' ? 'tot' : row.status,
    hinweis,
    http_status: code,
    abgerufen_am: new Date().toISOString(),
    _entscheidung: entscheidung,
  },
};

const abruf = $('Stufe 3: Browser-Abruf (Playwright)').first().json;
const row = $('Wenn von anderem Workflow aufgerufen').first().json;

// Prompt-Datei: "#"-Zeilen sind Kommentare, "=== ANFRAGE ===" trennt System und Anfrage.
const vorlage = String($json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in werte ? werte[k] : m));

return [
  {
    json: {
      system,
      anfrage: fuellen(anfrage, { URL: abruf.url, BUTTONS: abruf.consent.candidates.map((b) => '- ' + b).join('\n') }),
      seitentext: '',
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['button_text'],
        properties: { button_text: { type: 'string', description: 'Exakter Button-Text aus der Liste oder leer' } },
      },
      anbieter_override: row.anbieter_override || '',
      kontext: { url: abruf.url },
    },
  },
];

const row = $('Wenn von anderem Workflow aufgerufen').first().json;
const button = $json.ok && $json.daten ? String($json.daten.button_text || '') : '';
return [{ json: { url: row.url, consentButtonText: button } }];

const row = $('Wenn von anderem Workflow aufgerufen').first().json;
const r = $json;

// Hinweis: Im n8n-Code-Knoten gibt es kein "new URL(...)".
// Deshalb zerlegen wir Adressen mit einem regulären Ausdruck selbst.
function zerlegeUrl(roh) {
  const m = String(roh || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  return { protokoll: m[1].toLowerCase(), host: m[2].toLowerCase(), pfad: m[3] || '/', query: m[4] || '' };
}

// Macht aus einer relativen Weiterleitung ("/karriere") eine volle Adresse.
function absoluteUrl(ziel, basis) {
  if (/^https?:\/\//i.test(ziel)) return ziel;
  const b = zerlegeUrl(basis);
  if (!b) return ziel;
  if (ziel.startsWith('//')) return b.protokoll + ':' + ziel;
  if (ziel.startsWith('/')) return b.protokoll + '://' + b.host + ziel;
  return b.protokoll + '://' + b.host + b.pfad.replace(/[^\/]*$/, '') + ziel;
}

// Zeigt eine Adresse nur noch auf eine allgemeine Karriere- oder Startseite?
function istAllgemeineSeite(ziel, original) {
  const z = zerlegeUrl(ziel);
  const o = zerlegeUrl(original);
  if (!z || !o) return false;
  const pfad = (u) => u.pfad.replace(/\/+$/, '').toLowerCase();
  const host = (u) => u.host.replace(/^www\./, '');
  if (host(z) === host(o) && pfad(z) === pfad(o)) return false; // z. B. nur http -> https
  const p = pfad(z);
  if (p === '') return true;
  if (/^(\/[a-z]{2}(-[a-z]{2})?)?(\/(karriere|career|careers|jobs|job|stellenangebote|stellen|offene-stellen|jobboerse|join-us|joinus|vacancies|work-with-us|search|suche))*$/.test(p)) return true;
  if (/[?&](error|expired|notfound|jobnotfound)=/i.test(z.query)) return true;
  return false;
}

const basis = {
  id: row.id,
  url: row.url,
  http_status: r.httpStatus === undefined ? null : r.httpStatus,
  final_url: r.finalUrl || '',
  cache_id: r.cacheId || '',
  screenshot: r.screenshotUrl || '',
  text_hash: r.textHash || '',
  abgerufen_am: r.abgerufenAm || new Date().toISOString(),
};

let status = 'pruefen';
let hinweis = '';
const fehler = r.error ? (typeof r.error === 'string' ? r.error : r.error.message || JSON.stringify(r.error)) : '';
if (!r.ok) {
  status = 'fehler';
  hinweis = 'Abruf fehlgeschlagen: ' + (fehler || 'unbekannt');
} else if (r.httpStatus === 404 || r.httpStatus === 410) {
  status = 'tot';
  hinweis = `HTTP ${r.httpStatus}`;
} else if (istAllgemeineSeite(r.finalUrl, row.url)) {
  status = 'tot';
  hinweis = `Weitergeleitet auf allgemeine Seite: ${r.finalUrl}`;
} else if (r.blocked && r.blocked.any) {
  status = 'wartet_auf_freigabe';
  hinweis = 'Freigabe nötig: ' + (r.blocked.reasons || []).join(', ') + (row.mit_sitzung ? ' (auch mit gespeicherter Sitzung noch gesperrt)' : '');
} else if ((r.textLength || 0) < 200) {
  status = 'fehler';
  hinweis = 'Seite enthält kaum Text';
}

return [{ json: { ...basis, status, hinweis, _weiter: status === 'pruefen', _titel: r.title || '', _text: r.text || '' } }];

const abruf = $('Abruf auswerten').first().json;
const row = $('Wenn von anderem Workflow aufgerufen').first().json;

// Prompt-Datei zerlegen: "#"-Zeilen sind Kommentare für dich.
const vorlage = String($json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in werte ? werte[k] : m));

// ---- Das feste Antwortformat (JSON-Schema) ----
// Jedes Feld ist Pflicht; unbekannte Werte liefert das Modell als "".
const text = (beschreibung) => ({ type: 'string', description: beschreibung });
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: [
    'seitentyp', 'status', 'datum_zitat', 'veroeffentlichungsdatum', 'jobtitel', 'firma', 'ort', 'remote',
    'remote_regel_wortlaut', 'gehalt', 'vertragsform', 'bewerbungsweg', 'kurze_zusammenfassung', 'begruendung',
  ],
  properties: {
    seitentyp: { type: 'string', enum: ['einzelne_stelle', 'stellenliste', 'keine_stelle'] },
    status: { type: 'string', enum: ['aktiv', 'abgelaufen', 'unklar'] },
    datum_zitat: text('Wörtliche Textstelle mit dem Veröffentlichungsdatum oder leer'),
    veroeffentlichungsdatum: text('YYYY-MM-DD oder leer'),
    jobtitel: text('Jobtitel'),
    firma: text('Firmenname'),
    ort: text('Ort/Land'),
    remote: { type: 'string', enum: ['ja', 'nein', 'hybrid', 'unklar'] },
    remote_regel_wortlaut: text('Wörtliches Zitat zur Remote-Regel'),
    gehalt: text('Gehalt/Stundensatz wie angegeben'),
    vertragsform: text('z. B. Festanstellung, Freelance, EOR'),
    bewerbungsweg: text('z. B. Formular, E-Mail'),
    kurze_zusammenfassung: text('2–3 Sätze'),
    begruendung: text('1–2 Sätze zu status und seitentyp'),
  },
};

return [
  {
    json: {
      system,
      anfrage: fuellen(anfrage, { HEUTE: $now.toFormat('yyyy-MM-dd'), URL: abruf.url, TITEL: abruf._titel, SEITENTEXT: '{{SEITENTEXT}}' }),
      seitentext: abruf._text,
      schema: SCHEMA,
      anbieter_override: row.anbieter_override || '',
      funktion: 'fakten', // Modell laut Einstellungen: "Fakten auslesen"
      kontext: { id: abruf.id, url: abruf.url },
    },
  },
];

const abruf = $('Abruf auswerten').first().json;
const row = $('Wenn von anderem Workflow aufgerufen').first().json;
const k = $json; // Ergebnis von "00 KI-Aufruf"
const maxAlter = Number(row.max_alter_tage || 60);

const out = { ...abruf };
delete out._text;
out.modell_extraktion = `${k.anbieter || '?'}:${k.modell || '?'}`;

if (!k.ok) {
  out.status = 'fehler';
  out.hinweis = 'KI-Fehler: ' + (k.fehler || 'keine Antwort');
  out.dubletten_schluessel = '';
  return [{ json: out }];
}

const d = k.daten;
const leer = (v) => (v === undefined || v === null ? '' : String(v).trim());
for (const f of ['veroeffentlichungsdatum', 'jobtitel', 'firma', 'ort', 'remote', 'remote_regel_wortlaut', 'gehalt', 'vertragsform', 'bewerbungsweg', 'kurze_zusammenfassung', 'begruendung']) {
  out[f] = leer(d[f]);
}

// Gegen erfundene Daten: Steht die genannte Textstelle wirklich auf der Seite?
// (Kleine Modelle setzen gern einfach das heutige Datum ein.)
const zitat = leer(d.datum_zitat);
const normal = (s) => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
const belegt = zitat.length >= 3 && normal(abruf._text || '').includes(normal(zitat));
let datumHinweis = zitat ? `Datum aus: "${zitat}"` : '';
if (out.veroeffentlichungsdatum && !belegt) {
  datumHinweis = zitat ? `Datum verworfen ("${zitat}" steht nicht im Text)` : 'Datum verworfen (keine Textstelle genannt)';
  out.veroeffentlichungsdatum = '';
}

// Alter der Stelle in Tagen
let alter = null;
if (/^\d{4}-\d{2}-\d{2}$/.test(out.veroeffentlichungsdatum)) {
  const t = Date.parse(out.veroeffentlichungsdatum + 'T00:00:00Z');
  if (!isNaN(t)) alter = Math.max(0, Math.floor((Date.now() - t) / 86400000));
}
out.alter_tage = alter;

// ---- Regeln zum Aussortieren ----
if (d.seitentyp !== 'einzelne_stelle') {
  out.status = 'tot';
  out.hinweis = d.seitentyp === 'stellenliste' ? 'Keine einzelne Stelle (Übersicht/Liste)' : 'Keine Stellenanzeige';
} else if (d.status === 'abgelaufen') {
  out.status = 'abgelaufen';
  out.hinweis = 'Laut Seite abgelaufen';
} else if (alter !== null && alter > maxAlter) {
  out.status = 'zu_alt';
  out.hinweis = `Veröffentlicht vor ${alter} Tagen (Grenze: ${maxAlter})`;
} else if (alter === null) {
  out.status = 'unklar';
  out.hinweis = 'Kein Veröffentlichungsdatum gefunden – bleibt drin';
} else if (d.status === 'aktiv') {
  out.status = 'aktiv';
  out.hinweis = '';
} else {
  out.status = 'unklar';
  out.hinweis = 'Status laut KI unklar';
}
if (datumHinweis) out.hinweis = (out.hinweis ? out.hinweis + '; ' : '') + datumHinweis;
if (k.gekuerzt) out.hinweis = (out.hinweis ? out.hinweis + '; ' : '') + 'Seitentext für KI gekürzt';

// Schlüssel, um dieselbe Stelle unter anderer Adresse zu erkennen
const norm = (s) =>
  s.toLowerCase()
    .replace(/\((m|w|f|d|x|all genders|gn)[^)]*\)/g, '')
    .replace(/[^a-z0-9äöüß]+/g, ' ')
    .trim();
out.dubletten_schluessel = out.firma && out.jobtitel ? norm(out.firma) + '|' + norm(out.jobtitel) : '';
return [{ json: out }];

const cur = $('Stufe 5: Aussortieren').first().json;
const treffer = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.id && r.id !== cur.id && r.status !== 'duplikat' && r.status !== 'neu');
const out = { ...cur };
if (['aktiv', 'unklar'].includes(cur.status) && treffer.length > 0) {
  treffer.sort((a, b) => a.id - b.id);
  out.status = 'duplikat';
  out.duplikat_von = treffer[0].url;
  out.hinweis = `Gleiche Stelle wie ${treffer[0].url}`;
}
return [{ json: out }];

// Nur Felder, die es als Spalte in der Tabelle "jobs" gibt. Hilfsfelder (mit "_") fallen weg.
const SPALTEN = ["url","domain","linktext","erstmals_gesehen","nicht_mehr_gelistet","status","freigabe","hinweis","http_status","final_url","cache_id","screenshot","text_hash","dubletten_schluessel","duplikat_von","abgerufen_am","veroeffentlichungsdatum","alter_tage","jobtitel","firma","ort","remote","remote_regel_wortlaut","gehalt","vertragsform","bewerbungsweg","kurze_zusammenfassung","begruendung","modell_extraktion","passung_score","bewertung","bewertung_begruendung","pflichtkriterien_erfuellt","luecken","offene_fragen","warnsignale","modell_bewertung","bewertet_am"];
return $input.all().map((i) => {
  const r = i.json;
  const o = { id: r.id };
  for (const s of SPALTEN) {
    if (r[s] === undefined) continue;
    o[s] = r[s] !== null && typeof r[s] === 'object' ? JSON.stringify(r[s]) : r[s];
  }
  return { json: o };
});
